package com.seminarhub.domain.seminar.repository.querydsl;
import static com.seminarhub.domain.seminar.domain.QMemberSeminar.memberSeminar;
import com.querydsl.core.BooleanBuilder; import com.querydsl.core.types.dsl.ComparableExpressionBase; import com.querydsl.jpa.impl.JPAQueryFactory;
import com.seminarhub.domain.seminar.domain.MemberSeminar; import com.seminarhub.domain.seminar.service.MemberSeminarSearchQuery; import com.seminarhub.global.dto.CursorRequest; import com.seminarhub.global.repository.QuerydslRepositorySupport;
import java.util.List; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Repository; import org.springframework.util.CollectionUtils;
@Repository public class MemberSeminarRepositoryImpl extends QuerydslRepositorySupport<MemberSeminar> implements MemberSeminarRepositoryCustom {
    public MemberSeminarRepositoryImpl(JPAQueryFactory f){super(f,memberSeminar,memberSeminar.id,memberSeminar.createdAt,memberSeminar.updatedAt,memberSeminar.deletedAt);} public List<MemberSeminar> search(MemberSeminarSearchQuery q){return findAll(condition(q));} public Page<MemberSeminar> search(MemberSeminarSearchQuery q,Pageable p){return findAll(condition(q),p,this::sort);} public List<MemberSeminar> search(MemberSeminarSearchQuery q,CursorRequest c){return findByCursor(condition(q),c);}
    private BooleanBuilder condition(MemberSeminarSearchQuery q){BooleanBuilder b=auditCondition(q);if(q.memberId()!=null)b.and(memberSeminar.member.id.eq(q.memberId()));if(!CollectionUtils.isEmpty(q.memberIds()))b.and(memberSeminar.member.id.in(q.memberIds()));if(q.seminarId()!=null)b.and(memberSeminar.seminar.id.eq(q.seminarId()));if(!CollectionUtils.isEmpty(q.seminarIds()))b.and(memberSeminar.seminar.id.in(q.seminarIds()));return b;} private ComparableExpressionBase<?> sort(String n){return switch(n){case"id"->memberSeminar.id;case"memberId"->memberSeminar.member.id;case"seminarId"->memberSeminar.seminar.id;case"createdAt"->memberSeminar.createdAt;case"updatedAt"->memberSeminar.updatedAt;case"deletedAt"->memberSeminar.deletedAt;default->null;};}
}
